import React from 'react';
import './Gallery.css';

function Gallery({ artworks, loading }) {
  if (loading) {
    return <div className="gallery gallery--loading">Loading artwork...</div>;
  }

  if (!artworks.length) {
    return <div className="gallery gallery--empty">No artwork found. Try a different search.</div>;
  }

  return (
    <div className="gallery">
      {artworks.map((art) => (
        <figure className="gallery__item" key={art._id || art.id}>
          <img src={art.imageUrl} alt={art.title} loading="lazy" />
          <figcaption>
            <span className="gallery__title">{art.title}</span>
            <span className="gallery__artist">{art.artistName}</span>
          </figcaption>
        </figure>
      ))}
    </div>
  );
}

export default Gallery;
